#include "thermostat_thermostat.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void thermostat_thermostat_initialize(void);
void thermostat_thermostat_notify(microkit_channel channel);
void thermostat_thermostat_timeTriggered(void);

volatile sb_queue_Isolette_Data_Model_Temp_1_t *current_temp_queue_1;
sb_queue_Isolette_Data_Model_Temp_1_Recv_t current_temp_recv_queue;
volatile sb_queue_uint8_t_1_t *temp_changed_queue_1;
sb_queue_uint8_t_1_Recv_t temp_changed_recv_queue;
volatile sb_queue_Isolette_Data_Model_Set_Points_1_t *desired_temp_queue_1;
sb_queue_Isolette_Data_Model_Set_Points_1_Recv_t desired_temp_recv_queue;
volatile sb_queue_Isolette_Data_Model_On_Off_1_t *heat_control_queue_1;
volatile sb_queue_Isolette_Data_Model_Set_Points_1_t *sv_currentSetPoints_queue_1;
volatile sb_queue_Isolette_Data_Model_On_Off_1_t *sv_lastCmd_queue_1;

#define PORT_FROM_MON 0

volatile sb_event_counter_t *inj_clr_requests;
static sb_event_counter_t inj_clr_applied[2];

Isolette_Data_Model_Temp last_current_temp_payload;

bool get_current_temp(Isolette_Data_Model_Temp *data) {
  sb_event_counter_t numDropped;
  Isolette_Data_Model_Temp fresh_data;
  bool isFresh = sb_queue_Isolette_Data_Model_Temp_1_dequeue((sb_queue_Isolette_Data_Model_Temp_1_Recv_t *) &current_temp_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_current_temp_payload = fresh_data;
  }
  *data = last_current_temp_payload;
  return isFresh;
}

uintmax_t get_current_temp_num_invalid(void) {
  return sb_queue_Isolette_Data_Model_Temp_1_numInvalid((sb_queue_Isolette_Data_Model_Temp_1_Recv_t *) &current_temp_recv_queue);
}

bool temp_changed_is_empty(void) {
  return sb_queue_uint8_t_1_is_empty(&temp_changed_recv_queue);
}

bool get_temp_changed_poll(sb_event_counter_t *numDropped) {
  uint8_t eventPortPayload;
  uint8_t *data = &eventPortPayload;
  return sb_queue_uint8_t_1_dequeue((sb_queue_uint8_t_1_Recv_t *) &temp_changed_recv_queue, numDropped, data);
}

bool get_temp_changed() {
  sb_event_counter_t numDropped;
  return get_temp_changed_poll (&numDropped);
}

bool desired_temp_is_empty(void) {
  return sb_queue_Isolette_Data_Model_Set_Points_1_is_empty(&desired_temp_recv_queue);
}

bool get_desired_temp_poll(sb_event_counter_t *numDropped, Isolette_Data_Model_Set_Points *data) {
  return sb_queue_Isolette_Data_Model_Set_Points_1_dequeue((sb_queue_Isolette_Data_Model_Set_Points_1_Recv_t *) &desired_temp_recv_queue, numDropped, data);
}

bool get_desired_temp(Isolette_Data_Model_Set_Points *data) {
  sb_event_counter_t numDropped;
  return get_desired_temp_poll (&numDropped, data);
}

uintmax_t get_desired_temp_num_invalid(void) {
  return sb_queue_Isolette_Data_Model_Set_Points_1_numInvalid((sb_queue_Isolette_Data_Model_Set_Points_1_Recv_t *) &desired_temp_recv_queue);
}

bool put_heat_control(const Isolette_Data_Model_On_Off *data) {
  sb_queue_Isolette_Data_Model_On_Off_1_enqueue((sb_queue_Isolette_Data_Model_On_Off_1_t *) heat_control_queue_1, (Isolette_Data_Model_On_Off *) data);

  return true;
}

bool put_sv_currentSetPoints(const Isolette_Data_Model_Set_Points *data) {
  if (is_monitoring_enabled()) {
    sb_queue_Isolette_Data_Model_Set_Points_1_enqueue((sb_queue_Isolette_Data_Model_Set_Points_1_t *) sv_currentSetPoints_queue_1, (Isolette_Data_Model_Set_Points *) data);
  }

  return true;
}

bool put_sv_lastCmd(const Isolette_Data_Model_On_Off *data) {
  if (is_monitoring_enabled()) {
    sb_queue_Isolette_Data_Model_On_Off_1_enqueue((sb_queue_Isolette_Data_Model_On_Off_1_t *) sv_lastCmd_queue_1, (Isolette_Data_Model_On_Off *) data);
  }

  return true;
}

volatile sb_queue_Isolette_Data_Model_Set_Points_1_t *inj_sv_currentSetPoints_queue;
sb_queue_Isolette_Data_Model_Set_Points_1_Recv_t inj_sv_currentSetPoints_recv;

bool get_inj_sv_currentSetPoints(Isolette_Data_Model_Set_Points *value) {
  if (inj_sv_currentSetPoints_queue == NULL) {
    return false;
  }
  sb_event_counter_t numDropped;
  return sb_queue_Isolette_Data_Model_Set_Points_1_dequeue(&inj_sv_currentSetPoints_recv, &numDropped, value);
}

volatile sb_queue_Isolette_Data_Model_On_Off_1_t *inj_sv_lastCmd_queue;
sb_queue_Isolette_Data_Model_On_Off_1_Recv_t inj_sv_lastCmd_recv;

bool get_inj_sv_lastCmd(Isolette_Data_Model_On_Off *value) {
  if (inj_sv_lastCmd_queue == NULL) {
    return false;
  }
  sb_event_counter_t numDropped;
  return sb_queue_Isolette_Data_Model_On_Off_1_dequeue(&inj_sv_lastCmd_recv, &numDropped, value);
}

bool is_injection_enabled(void) {
  return inj_sv_currentSetPoints_queue != NULL && inj_sv_lastCmd_queue != NULL;
}

bool is_monitoring_enabled(void) {
  return sv_currentSetPoints_queue_1 != NULL && sv_lastCmd_queue_1 != NULL;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Isolette_Data_Model_Temp_1_Recv_init(&current_temp_recv_queue, (sb_queue_Isolette_Data_Model_Temp_1_t *) current_temp_queue_1);

  sb_queue_uint8_t_1_Recv_init(&temp_changed_recv_queue, (sb_queue_uint8_t_1_t *) temp_changed_queue_1);

  sb_queue_Isolette_Data_Model_Set_Points_1_Recv_init(&desired_temp_recv_queue, (sb_queue_Isolette_Data_Model_Set_Points_1_t *) desired_temp_queue_1);

  sb_queue_Isolette_Data_Model_On_Off_1_init((sb_queue_Isolette_Data_Model_On_Off_1_t *) heat_control_queue_1);

  sb_queue_Isolette_Data_Model_Set_Points_1_init((sb_queue_Isolette_Data_Model_Set_Points_1_t *) sv_currentSetPoints_queue_1);

  sb_queue_Isolette_Data_Model_On_Off_1_init((sb_queue_Isolette_Data_Model_On_Off_1_t *) sv_lastCmd_queue_1);

  if (inj_sv_currentSetPoints_queue != NULL) {
    sb_queue_Isolette_Data_Model_Set_Points_1_Recv_init(&inj_sv_currentSetPoints_recv, (sb_queue_Isolette_Data_Model_Set_Points_1_t *) inj_sv_currentSetPoints_queue);
  }

  if (inj_sv_lastCmd_queue != NULL) {
    sb_queue_Isolette_Data_Model_On_Off_1_Recv_init(&inj_sv_lastCmd_recv, (sb_queue_Isolette_Data_Model_On_Off_1_t *) inj_sv_lastCmd_queue);
  }

  thermostat_thermostat_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      if (inj_clr_requests != NULL) {
        if (inj_clr_requests[0] != inj_clr_applied[0]) {
          inj_clr_applied[0] = inj_clr_requests[0];
          __atomic_thread_fence(__ATOMIC_ACQUIRE);
          sb_event_counter_t cutoff = inj_clr_requests[1];
          // behind the cutoff: the difference taken as signed survives a wrap
          if ((intmax_t) (cutoff - temp_changed_recv_queue.numRecv) > 0) {
            temp_changed_recv_queue.numRecv = cutoff;
          }
        }
        if (inj_clr_requests[2] != inj_clr_applied[1]) {
          inj_clr_applied[1] = inj_clr_requests[2];
          __atomic_thread_fence(__ATOMIC_ACQUIRE);
          sb_event_counter_t cutoff = inj_clr_requests[3];
          // behind the cutoff: the difference taken as signed survives a wrap
          if ((intmax_t) (cutoff - desired_temp_recv_queue.numRecv) > 0) {
            desired_temp_recv_queue.numRecv = cutoff;
          }
        }
      }

      thermostat_thermostat_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      thermostat_thermostat_notify(channel);
  }
}
